// --- Brick Collision Resolution ------------------------------------------

// Handles brick collisions, including per-face bounce, push-out, and tunnelling.
// This was extracted from frame() to resolve BUG #1 and facilitate testing.
export function resolveBrickCollisions(state, dt) {
  const { ball } = state;
  const prevX = ball.x - ball.vx * dt;
  const prevY = ball.y - ball.vy * dt;

  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    const minX = brick.x - ball.r;
    const maxX = brick.x + brick.w + ball.r;
    const minY = brick.y - ball.r;
    const maxY = brick.y + brick.h + ball.r;

    let tMinX = -Infinity, tMaxX = Infinity;
    if (ball.vx !== 0) {
      const tx1 = (minX - prevX) / ball.vx;
      const tx2 = (maxX - prevX) / ball.vx;
      tMinX = Math.min(tx1, tx2);
      tMaxX = Math.max(tx1, tx2);
    } else if (prevX < minX || prevX > maxX) {
      continue;
    }

    let tMinY = -Infinity, tMaxY = Infinity;
    if (ball.vy !== 0) {
      const ty1 = (minY - prevY) / ball.vy;
      const ty2 = (maxY - prevY) / ball.vy;
      tMinY = Math.min(ty1, ty2);
      tMaxY = Math.max(ty1, ty2);
    } else if (prevY < minY || prevY > maxY) {
      continue;
    }

    const tMin = Math.max(0, Math.max(tMinX, tMinY));
    const tMax = Math.min(1, Math.min(tMaxX, tMaxY));

    if (tMin <= tMax) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      if (tMinX > tMinY) {
        ball.vx = -ball.vx;
        ball.x = (ball.vx > 0) ? maxX : minX;
      } else if (tMinY > tMinX) {
        ball.vy = -ball.vy;
        ball.y = (ball.vy > 0) ? maxY : minY;
      } else {
        ball.vx = -ball.vx;
        ball.vy = -ball.vy;
        ball.x = (ball.vx > 0) ? maxX : minX;
        ball.y = (ball.vy > 0) ? maxY : minY;
      }
    }
  }
}

